(()=>{
'use strict';
const shell=document.querySelector('.terminal-shell'),form=document.getElementById('contact-form'),name=document.getElementById('contact-name'),email=document.getElementById('contact-email'),project=document.getElementById('contact-project'),submit=document.getElementById('contact-submit'),copy=document.getElementById('contact-copy'),error=document.getElementById('contact-error'),result=document.getElementById('contact-result'),output=document.getElementById('contact-brief');
const controls=[name,email,project],recipient=shell.dataset.contactEmail.trim(),recipientReady=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipient);
submit.textContent=recipientReady?'open email draft ↗':'copy project brief ↵';copy.hidden=!recipientReady;
function values(){error.textContent='';controls.forEach(control=>control.removeAttribute('aria-invalid'));for(const control of controls){if(!control.value.trim()){control.setAttribute('aria-invalid','true');error.textContent=control===name?'Add your name.':control===email?'Add an email address so we can reply.':'Tell us a little about the project.';control.focus();return null;}if(!control.checkValidity()){control.setAttribute('aria-invalid','true');control.reportValidity();return null;}}return{name:name.value.trim(),email:email.value.trim(),project:project.value.trim()};}
function briefText(answers){return `New project enquiry\n\nName: ${answers.name}\nEmail: ${answers.email}\n\nProject\n${answers.project}\n`;}
async function copyBrief(answers){const text=briefText(answers);try{if(!navigator.clipboard?.writeText)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(text);output.hidden=true;result.textContent='Brief copied.';}catch{output.textContent=text;output.hidden=false;const range=document.createRange();range.selectNodeContents(output);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);result.textContent='Your brief is selected below. Copy it with your usual keyboard shortcut.';}}
form.addEventListener('submit',async event=>{event.preventDefault();const answers=values();if(!answers)return;if(!recipientReady){await copyBrief(answers);return;}const address=recipient.split('@').map(encodeURIComponent).join('@'),subject=encodeURIComponent(`Project enquiry — ${answers.name}`),body=encodeURIComponent(briefText(answers));location.href=`mailto:${address}?subject=${subject}&body=${body}`;result.textContent='Your email app will open with the brief. Send it from there.';});
copy.onclick=async()=>{const answers=values();if(answers)await copyBrief(answers);};
form.addEventListener('input',event=>{event.target.removeAttribute('aria-invalid');error.textContent='';result.textContent='';output.hidden=true;});
project.addEventListener('keydown',event=>{if(event.key==='Enter'&&(event.metaKey||event.ctrlKey)){event.preventDefault();form.requestSubmit();}});
window.addEventListener('contact:open',()=>{const control=controls.find(control=>!control.value.trim())||project;control.focus({preventScroll:true});});
new IntersectionObserver((entries,observer)=>{for(const entry of entries)if(entry.isIntersecting){shell.classList.add('is-live');observer.unobserve(shell);}},{threshold:.2}).observe(shell);
})();
